// Radar Bellajour — construit le corps du mail a partir des fiches Notion.
const items = $input.all();

function toText(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return v.map(toText).join(' ');
  if (typeof v === 'object') {
    if (typeof v.plain_text === 'string') return v.plain_text;
    if (Array.isArray(v.title)) return v.title.map(t => t.plain_text || '').join('');
    if (Array.isArray(v.rich_text)) return v.rich_text.map(t => t.plain_text || '').join('');
    if (v.formula) return toText(v.formula.string ?? v.formula.number ?? v.formula.boolean ?? '');
    if (v.select && v.select.name) return v.select.name;
    if (v.status && v.status.name) return v.status.name;
    if (v.date && v.date.start) return v.date.start;
    if (typeof v.name === 'string') return v.name;
    if (typeof v.string === 'string') return v.string;
    if (typeof v.start === 'string') return v.start;
    return '';
  }
  return '';
}

function getProp(row, name) {
  const j = row.json || {};
  if (j.properties && j.properties[name] !== undefined) return toText(j.properties[name]);
  if (j[name] !== undefined) return toText(j[name]);
  return '';
}

const actions = [];
const relances = [];

for (const row of items) {
  const action = (getProp(row, 'property_prochaine_action') || getProp(row, '\ud83d\udc49 Prochaine action')).trim();
  if (!action) continue; // on ignore les fiches sans prochaine action
  const qui = getProp(row, 'property_qui') || getProp(row, 'Qui');
  const compte = (getProp(row, 'property_compte_instagram') || getProp(row, 'Compte Instagram')).trim();
  const prenom = (getProp(row, 'property_pr_nom') || getProp(row, 'Prenom')).trim() || getProp(row, 'Pr\u00e9nom').trim();
  const label = compte || prenom || 'Sans nom';
  const dateStr = (getProp(row, 'property_derni_re_action_le') || getProp(row, 'Derniere action le')).trim() || getProp(row, 'Derni\u00e8re action le').trim();
  let ts = dateStr ? Date.parse(dateStr) : Number.POSITIVE_INFINITY;
  if (isNaN(ts)) ts = Number.POSITIVE_INFINITY;
  const entry = { label, action, ts };
  if (qui.includes('faire (toi)')) actions.push(entry);
  else if (qui.includes('relancer (elle)')) relances.push(entry);
}

// tri par derniere action croissant (plus ancien en haut)
actions.sort((a, b) => a.ts - b.ts);
relances.sort((a, b) => a.ts - b.ts);

const dateJour = new Date().toLocaleDateString('fr-FR', { timeZone: 'Europe/Lisbon', day: '2-digit', month: '2-digit', year: 'numeric' });

function render(list) {
  if (!list.length) return "Rien aujourd'hui \u2728";
  return list.map(e => '\u2022 ' + e.label + ' \u2014 ' + e.action).join('\n');
}

const subject = '\ud83c\udfaf Radar Bellajour \u2014 ' + dateJour;
const body = [
  subject,
  '',
  '\u2705 A FAIRE',
  render(actions),
  '',
  '\ud83d\udd14 A RELANCER',
  render(relances),
  ''
].join('\n');

return [{ json: { subject, body, actionsCount: actions.length, relancesCount: relances.length } }];
